  "inlineSchema": "// Smart Campus Management System\n// Complete College Hierarchy: Dean → Department → HOD → Faculty → Student → Student Portal\n// Prisma Schema Definition\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id        Int      @id @default(autoincrement())\n  email     String   @unique\n  password  String\n  name      String\n  role      String // \"ADMIN\", \"DEAN\", \"HOD\", \"FACULTY\", \"STUDENT\"\n  phone     String?\n  status    String   @default(\"ACTIVE\")\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  facultyProfile    Faculty?\n  managedDepartment Department? @relation(\"DepartmentHOD\")\n  studentProfile    Student?\n  auditLogs         AuditLog[]\n\n  @@index([email])\n  @@index([role])\n}\n\nmodel Department {\n  id          Int      @id @default(autoincrement())\n  code        String   @unique // e.g. \"ECE\", \"CSE\"\n  name        String   @unique\n  description String?\n  hodId       Int?     @unique\n  status      String   @default(\"ACTIVE\")\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  hod            User?          @relation(\"DepartmentHOD\", fields: [hodId], references: [id])\n  facultyMembers Faculty[]\n  students       Student[]\n  subjects       Subject[]\n  notifications  Notification[]\n\n  @@index([code])\n}\n\nmodel Faculty {\n  id             Int      @id @default(autoincrement())\n  facultyCode    String   @unique // e.g. \"FAC-CSE-001\"\n  userId         Int      @unique\n  departmentId   Int\n  designation    String // e.g. \"Professor & HOD\", \"Associate Professor\", \"Assistant Professor\"\n  subjectsTaught String   @default(\"Core Engineering\")\n  joiningDate    DateTime @default(now())\n  maxCapacity    Int      @default(35)\n  status         String   @default(\"ACTIVE\")\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  user       User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  department Department @relation(fields: [departmentId], references: [id], onDelete: Restrict)\n  students   Student[]\n\n  @@index([facultyCode])\n  @@index([departmentId])\n  @@index([status])\n}\n\nmodel Student {\n  id             Int      @id @default(autoincrement())\n  studentId      String   @unique // e.g. \"CSE2026001\"\n  userId         Int?     @unique\n  name           String\n  email          String   @unique\n  phone          String?\n  departmentId   Int\n  facultyId      Int?\n  academicYear   String   @default(\"2024-2028\")\n  semester       Int      @default(4)\n  section        String   @default(\"A\")\n  enrollmentDate DateTime @default(now())\n  status         String   @default(\"ACTIVE\")\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  user       User?      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  department Department @relation(fields: [departmentId], references: [id], onDelete: Restrict)\n  faculty    Faculty?   @relation(fields: [facultyId], references: [id], onDelete: SetNull)\n\n  @@index([studentId])\n  @@index([departmentId])\n  @@index([facultyId])\n  @@index([status])\n}\n\nmodel Subject {\n  id           Int      @id @default(autoincrement())\n  code         String // e.g. \"CS401\"\n  name         String // e.g. \"Design and Analysis of Algorithms\"\n  credits      Int      @default(4)\n  semester     Int      @default(4)\n  departmentId Int\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  department Department @relation(fields: [departmentId], references: [id], onDelete: Cascade)\n\n  @@index([code])\n  @@index([departmentId])\n}\n\nmodel Notification {\n  id           Int      @id @default(autoincrement())\n  title        String\n  message      String\n  sender       String // e.g. \"Dean's Office\", \"HOD - CSE\", \"Academic Affairs\"\n  targetRole   String   @default(\"ALL\") // \"ALL\", \"STUDENT\", \"FACULTY\", \"HOD\", \"DEAN\"\n  departmentId Int?\n  isRead       Boolean  @default(false)\n  createdAt    DateTime @default(now())\n\n  department Department? @relation(fields: [departmentId], references: [id], onDelete: SetNull)\n\n  @@index([targetRole])\n  @@index([departmentId])\n  @@index([createdAt])\n}\n\nmodel AuditLog {\n  id        Int      @id @default(autoincrement())\n  userId    Int?\n  userName  String\n  action    String\n  entity    String\n  entityId  String?\n  details   String?\n  ipAddress String?\n  createdAt DateTime @default(now())\n\n  user User? @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  @@index([createdAt])\n  @@index([action])\n}\n",
